WITH with_windows AS (SELECT id, txn_type, merchant, COUNT(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_amount, SUM(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_amount, AVG(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_amount FROM transactions), deduped AS (SELECT *, RANK() OVER (PARTITION BY merchant ORDER BY last3_count_amount DESC NULLS LAST) AS dedup_rank FROM with_windows QUALIFY dedup_rank = 1), deduped_transactions AS (SELECT id, merchant, last3_sum_amount, last3_avg_amount FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY last3_sum_amount NULLS LAST, id) AS dedup_rank_2 FROM deduped) t WHERE dedup_rank_2 = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY last3_avg_amount DESC NULLS FIRST, id) AS rank_in_group FROM deduped_transactions QUALIFY rank_in_group = 1), filtered AS (SELECT id, merchant, last3_sum_amount, LEAST(last3_avg_amount, rank_in_group) AS least_last3_avg_amount_rank_in_group, CEIL(last3_sum_amount) AS last3_sum_amount_whole FROM ranked WHERE last3_sum_amount > 9000), stats AS (SELECT CASE WHEN last3_sum_amount >= 20400 THEN 'HIGH' ELSE 'LOW' END AS last3_sum_amount_tier, merchant, COUNT(*) FILTER (WHERE merchant = 'Shell') AS shell_rows, SIZE(COLLECT_SET(merchant)) AS num_merchants, SUM(last3_sum_amount_whole) AS total_last3_sum_amount_whole, COUNT(CASE WHEN merchant = 'Shell' THEN 1 END) AS shell_count, RANK() OVER (PARTITION BY CASE WHEN last3_sum_amount >= 20400 THEN 'HIGH' ELSE 'LOW' END ORDER BY SUM(last3_sum_amount_whole) DESC) AS total_last3_sum_amount_whole_rank FROM filtered GROUP BY CASE WHEN last3_sum_amount >= 20400 THEN 'HIGH' ELSE 'LOW' END, merchant) SELECT last3_sum_amount_tier, merchant, shell_rows, num_merchants, shell_count, total_last3_sum_amount_whole_rank FROM stats ORDER BY total_last3_sum_amount_whole_rank;
